**Remediation (DSC)**:
```powershell
Configuration RemoveWmiPersistence {
    Import-DscResource -ModuleName xPSDesiredStateConfiguration
    Node localhost {
        Script RemoveWmiSubscriptions {
            GetScript = { @{ Result = "OK" } }
            TestScript = { (Get-WmiObject __EventFilter | Measure).Count -eq 0 }
            SetScript = { Get-WmiObject __EventFilter | Remove-WmiObject }
        }
    }
}
